import{_ as h,C as n,o as t,c as s,j as e,a as i,b as l,w as o,E as d,ad as p,ac as g}from"./chunks/framework.Bzw8ikz_.js";const c="/hubHooks/assets/%E7%BD%91%E6%A0%BC%E6%9D%90%E8%B4%A8.bZOM738F.svg",E="/hubHooks/assets/%E5%85%89.D19Aum2n.png",L=JSON.parse('{"title":"光源与阴影","description":"","frontmatter":{},"headers":[],"relativePath":"web3d/three/光源与阴影.md","filePath":"web3d/three/光源与阴影.md","lastUpdated":1774572133000}'),m={name:"web3d/three/光源与阴影.md"};function A(b,a,B,u,D,_){const r=n("Mermaid");return t(),s("div",null,[a[1]||(a[1]=e("h1",{id:"光源与阴影",tabindex:"-1"},[i("光源与阴影 "),e("a",{class:"header-anchor",href:"#光源与阴影","aria-label":'Permalink to "光源与阴影"'},"​")],-1)),(t(),l(p,null,{default:o(()=>[d(r,{id:"mermaid-3",class:"mermaid",graph:"%0Aflowchart%20LR%0A%20%20%20%20A%5B%E5%85%89%E6%BA%90%5D%20--%3E%20B%5B%E7%8E%AF%E5%A2%83%E5%85%89%5D%0A%20%20%20%20B%20--%3E%20B1%5BAmbientLight%5D%0A%20%20%20%20A%20--%3E%20C%5B%E7%82%B9%E5%85%89%E6%BA%90%5D%0A%20%20%20%20C%20--%3E%20C1%5BPointLight%5D%0A%20%20%20%20A%20--%3E%20D%5B%E8%81%9A%E5%85%89%E7%81%AF%E5%85%89%E6%BA%90%5D%0A%20%20%20%20D%20--%3E%20D1%5BSpotLight%5D%0A%20%20%20%20A%20--%3E%20E%5B%E5%B9%B3%E8%A1%8C%E5%85%89%5D%0A%20%20%20%20E%20--%3E%20E1%5BDirectionalLight%5D%0A%20%20%20%20A%20--%3E%20F%5B%E5%8D%8A%E7%90%83%E5%85%89%5D%0A%20%20%20%20F%20--%3E%20F1%5BHemisphereLight%5D%0A%20%20%20%20A%20--%3E%20G%5B%E7%9F%A9%E5%BD%A2%E5%8C%BA%E5%9F%9F%E5%85%89%5D%0A%20%20%20%20G%20--%3E%20G1%5BRectAreaLight%5D%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=g('<h2 id="光源" tabindex="-1">光源 <a class="header-anchor" href="#光源" aria-label="Permalink to &quot;光源&quot;">​</a></h2><h3 id="环境光ambientlight" tabindex="-1">环境光AmbientLight <a class="header-anchor" href="#环境光ambientlight" aria-label="Permalink to &quot;环境光AmbientLight&quot;">​</a></h3><p><strong>环境光AmbientLight</strong>没有特定方向，只是简单地将材质的颜色与光照颜色进行叠加（PhotoShop 里的正片叠底模式），再乘以光照强度。无法产生阴影，只是整体改变场景的光照明暗。</p><h3 id="点光源pointlight" tabindex="-1">点光源PointLight <a class="header-anchor" href="#点光源pointlight" aria-label="Permalink to &quot;点光源PointLight&quot;">​</a></h3><p><strong>点光源PointLight</strong>可以类比为一个发光点，就像生活中一个灯泡以灯泡为中心向四周发射光线。</p><p>点光源（PointLight）有额外的一个范围（distance）属性。 如果 distance 设为 0，则光线可以照射到无限远处。如果大于 0，则只可以照射到指定的范围，光照强度在这个过程中逐渐衰减，在光源位置时，intensity 是设定的大小，在距离光源 distance 位置的时候，intensity 为 0。</p><h3 id="平行光directionallight" tabindex="-1">平行光DirectionalLight <a class="header-anchor" href="#平行光directionallight" aria-label="Permalink to &quot;平行光DirectionalLight&quot;">​</a></h3><p><strong>平行光DirectionalLight</strong>就是沿着特定方向发射。</p><p>平行光又称方向光（DirectionalLight）常常用来表现太阳光照的效果</p><h3 id="聚光源spotlight" tabindex="-1">聚光源SpotLight <a class="header-anchor" href="#聚光源spotlight" aria-label="Permalink to &quot;聚光源SpotLight&quot;">​</a></h3><p><strong>聚光源SpotLight</strong>可以认为是一个沿着特定方会逐渐发散的光源，照射范围在三维空间中构成一个圆锥体。</p><p>聚光灯可以看成是一个点光源被一个圆锥体限制住了光照的范围。实际上有两个圆锥，内圆锥和外圆锥。光照强度在两个锥体之间从设定的强度递减到0</p><h3 id="半球光hemispherelight" tabindex="-1">半球光HemisphereLight <a class="header-anchor" href="#半球光hemispherelight" aria-label="Permalink to &quot;半球光HemisphereLight&quot;">​</a></h3><p>半球光（HemisphereLight）的颜色是从天空到地面两个颜色之间的渐变，与物体材质的颜色作叠加后得到最终的颜色效果。一个点受到的光照颜色是由所在平面的朝向（法向量）决定的 —— 面向正上方就受到天空的光照颜色，面向正下方就受到地面的光照颜色，其他角度则是两个颜色渐变区间的颜色。</p><h2 id="光源对物体表面影响" tabindex="-1">光源对物体表面影响 <a class="header-anchor" href="#光源对物体表面影响" aria-label="Permalink to &quot;光源对物体表面影响&quot;">​</a></h2><p><img src="'+c+'" alt="网格材质"></p><h2 id="阴影" tabindex="-1">阴影 <a class="header-anchor" href="#阴影" aria-label="Permalink to &quot;阴影&quot;">​</a></h2><p>Shadow Map（阴影贴图）实现原理：首先将光源想像成一个相机对场景做第一次渲染，将光源所能看到的所有场景物体的深度写入z-buffer中，如果光源为平行光，如太阳，光源将对观察者所看到的视锥体内的所有物体投射阴影， 光源使用正交投影，投影的视图的宽(x),高(y)要设置得足够大来包含所有可视物体。如果光源为局部(Local) 光源，也需要做类似调整，如果局部光源离投影阴影的物体足够远，一个视锥体就可以包含这些物体， 特别地，如果 局部光源是一盏聚光灯( spotlight)，它本身与有一个视锥关联，视锥外的一切物体都认为是不会受光照影响。 并不是场景中的所有物体都要渲染到shadow map中，只有投影阴影的物体才需要被渲染。例如，如果已知地面只接收阴影而不投影阴影，那么就不需要将其渲染到shadow map。</p><p>阴影贴图的工作方式就是具有投射阴影的光能对所有能被投射阴影的物体从光源渲染阴影。 <img src="'+E+'" alt="光"></p><h2 id="雾" tabindex="-1">雾 <a class="header-anchor" href="#雾" aria-label="Permalink to &quot;雾&quot;">​</a></h2><p>在3D引擎里，雾通常是基于离摄像机的距离褪色至某种特定颜色的方式。在three.js中添加雾是通过创建 Fog 或者 FogExp2 实例并设定scene的fog 属性。 Fog 让你设定 near 和 far 属性，代表距离摄像机的距离。任何物体比 near 近不会受到影响，任何物体比 far 远则完全是雾的颜色。在 near 和 far 中间的物体，会从它们自身材料的颜色褪色到雾的颜色。 FogExp2 会根据离摄像机的距离呈指数增长。</p>',21))])}const P=h(m,[["render",A]]);export{L as __pageData,P as default};
